#!/usr/bin/env python3
"""Finite current unsupported cohorts. Run catalog_snapshot.mjs first if sources change."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
hashes={}
def read(p):
 b=(ROOT/p).read_bytes();hashes[p]=hashlib.sha256(b).hexdigest();return json.loads(b)
b=read('research/native/coverage-20261114/baseline-catalog.json')
assert b['counts']=={'melee':{'total':82,'supported':35},'ranged':{'total':71,'supported':11},'armor':{'total':73,'supported':13},'artifact':{'total':45,'supported':3}}
uns={k:{x['id'] for x in b['items'] if x['category']==k and x['runtimeSupport']=='unsupported'} for k in b['counts']}
a=read('research/armor-audit.json')['entries'];r=read('research/ranged-weapon-audit.json')['entries'];m=read('research/melee-attack-profile-audit.json')['weapons'];ad=read('research/artifact-audit.json');t=ad['entries']+ad['populationDifferences']
rows={k:[x for x in v if x.get('id',x.get('weaponId')) in uns[k]] for k,v in [('armor',a),('ranged',r),('melee',m),('artifact',t)]}
def ids(v):return sorted(x.get('id',x.get('weaponId')) for x in v)
def cohort(v):return {'affectedUnsupportedCount':len(v),'ids':ids(v),'automaticRuntimeUnlockCount':0}
armor={k:cohort([x for x in rows['armor'] if any(p['kind']==k for p in x['intrinsicProperties'])]) for k in sorted({p['kind'] for x in rows['armor'] for p in x['intrinsicProperties']})}
artifact={k:{v:cohort([x for x in rows['artifact'] if x.get(k,'unknown')==v]) for v in sorted({x.get(k,'unknown') for x in rows['artifact']})} for k in ['mechanicFamily','runtimeReadiness']}
artifact['powerScaling']={v:cohort([x for x in rows['artifact'] if x.get('powerScaling',{}).get('kind','unknown')==v]) for v in sorted({x.get('powerScaling',{}).get('kind','unknown') for x in rows['artifact']})}
artifact['cooldownReported']=cohort([x for x in rows['artifact'] if x.get('cooldown',{}).get('seconds') is not None])
artifact['soulRequired']=cohort([x for x in rows['artifact'] if x.get('soul',{}).get('required') is True])
artifact['targetingUnknown']=cohort([x for x in rows['artifact'] if x.get('targeting',{}).get('status')=='unknown'])
ranged={'windPull':cohort([x for x in rows['ranged'] if x['family']=='wind-bow']),'fixedPunch':cohort([x for x in rows['ranged'] if 'Built in: Punch' in x['intrinsic']['own']]),'simultaneousProjectileFamily':cohort([x for x in rows['ranged'] if x['family'] in ['dual-crossbows','scatter-crossbow'] or x['id'] in ['webbed-bow','winter-s-touch']]),'fixedMultishot':cohort([x for x in rows['ranged'] if 'Built in: Multishot' in x['intrinsic']['own']]),'completeCycle':cohort(rows['ranged']),'burstCycle':cohort([x for x in rows['ranged'] if x['firingMode']=='burst']),'windUpCycle':cohort([x for x in rows['ranged'] if x['firingMode']=='wind-up'])}
melee={'chains':cohort([x for x in rows['melee'] if x['weaponId'] in ['flail','jailors-scythe']]),'auditSpecialHandlingFlag':cohort([x for x in rows['melee'] if x['specialHandlingRequired']])}
i=read('research/domain/formal/identity-evidence-v1.json')['identityAssertions'];v=read('research/domain/formal/value-availability-v2.json')['valueProjections'];rel=read('research/domain/formal/serialized-relation-v2.json')['relationProjections'];c=read('research/domain/game-data-canonical-mappings.json')['mappings'];raw=read('research/raw/game-data-raw-structural-inventory/manifest.json')['catalogSeeds'];read('research/domain/game-data-canonical-properties.json')
evidence=[]
for cat,eids in uns.items():
 for eid in sorted(eids):
  evidence.append(dict(category=cat,id=eid,rawSeeds=[dict(status=z['status'],candidates=[p['packagePath'] for p in z['candidates']]) for z in raw if z['catalogId']==eid and z['category']==cat],identityAssertions=[dict(id=z['id'],reviewState=z['reviewState'],rawIdentity=z['rawIdentity'],packagePath=z['applicationScope']['packagePath']) for z in i if z['domainId']==eid],formalValueProjections=[dict(id=z['projectionId'],result=z['result']) for z in v if z['occurrence']['domainId']==eid],formalRelationProjections=[dict(id=z['projectionRef'],result=z['result']) for z in rel if z['occurrence']['domainId']==eid],canonicalMappingIds=[z['id'] for z in c if z.get('canonicalEntity') in [eid,f'{cat}:{eid}',f'{cat}-weapon:{eid}']]))
d=dict(schemaVersion=1,artifactKind='common-blocker-finite-census',baselineCommit='6bf212dc5ea8f686f981c9882657874264e41791',runtimePromotion=False,evidenceStatus='analysis-only',counts=b['counts'],unsupportedIds={k:sorted(s) for k,s in uns.items()},cohorts=dict(armor=armor,artifact=artifact,ranged=ranged,melee=melee),entityEvidence=evidence,boundaries=['Cohorts overlap; do not sum.','Affected count is a research beneficiary count, not immediate unlock.','Native scalar reuse does not close target, cycle, state, or intrinsic blockers.','Corrupted Seeds is included as the 45th Artifact populationDifference.','Existing supported self buffs are not counted as new beneficiaries.','Unknown remains unknown; no runtime or Formal promotion.'],inputSha256=hashes)
(OUT/'candidate-census.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
lines=['# Current common blocker census','', 'Baseline `6bf212dc5ea8f686f981c9882657874264e41791`. Current registered catalog: M35/82, R11/71, Armor13/73, Artifact3/45. Research only; no runtime promotion.','', '| Candidate | Unsupported affected | Important qualification |','|---|---:|---|']
for label,n,note in [('Artifact damage Power',17,'Target, event, cost still required'),('Artifact duration-only',7,'Target/state/objective are separate'),('Armor hit negation',11,'Discrete hit semantics, not scalar DR'),('Armor DR',15,'Other intrinsics coexist'),('Armor arrows/bundle',3,'All three obtainable; other intrinsic blockers remain'),('Ranged complete cycle',60,'Shared foundation, not 60 unlocks'),('Ranged Wind pull',3,'Two variants add other fixed effects'),('Ranged simultaneous projectiles',ranged['simultaneousProjectileFamily']['affectedUnsupportedCount'],'Fixed Multishot 1 is a separate cohort'),('Ranged Punch',1,'Doom Crossbow; cannot silently ignore pushback'),('Melee Chains',2,'Flail and Jailor; explicit no other eligible Chain candidate condition')]:lines.append(f'| {label} | {n} | {note} |')
lines+=['','All finite IDs and current Raw seed/Formal identity/value/relation locators are in candidate-census.json. Cohorts overlap. Automatic runtime unlock is zero. Historical audit blockers are not authoritative runtime counts; the baseline snapshot executes the current catalog.','', 'The seven duration-only unsupported artifacts are Boots of Swiftness, Fishing Rod, Ghost Cloak, Gong of Weakening, Light Feather, Shadow Shifter, Totem of Shielding. Native DurationIncrease alone is insufficient to grant any of them.','', 'Reproduce: regenerate baseline-catalog.json with catalog_snapshot.mjs, then run `python3 -B research/native/coverage-20261114/candidate_census.py`.']
(OUT/'candidate-census.md').write_text('\n'.join(lines)+'\n');print(json.dumps({k:{f:x['affectedUnsupportedCount'] for f,x in z.items()} for k,z in [('armor',armor),('ranged',ranged),('melee',melee)]}))
